node -e "
const fs = require('fs');
const db = fs.readFileSync('/workspace/world.db');
console.log('DB size:', db.length);
console.log('Header:', db.slice(0,16).toString());
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\\n' + t.name + ':', info.map(c => c.name + '(' + c.type + ')').join(', '));
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const user = db.prepare(\"SELECT * FROM users WHERE email = ?\").get('maya.chen.travel@example.com');
if (user) {
  console.log(JSON.stringify(user, null, 2));
} else {
  console.log('No user found with that email');
  // Try partial match
  const users = db.prepare(\"SELECT user_id, name, email FROM users WHERE email LIKE '%maya%' OR name LIKE '%maya%'\").all();
  console.log('Partial matches:', JSON.stringify(users, null, 2));
}
"

